<?php
function admin_start(string $action,string $section,bool $upload=false): void { echo '<form class="admin-form" method="post" action="/admin/'.e($section).'"'.($upload?' enctype="multipart/form-data"':'').'>'.csrf_field().'<input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="section" value="'.e($section).'">'; }
function admin_field(string $name,string $label,string $type='text',mixed $value='',bool $required=true): void { echo '<label>'.e($label).'<input name="'.e($name).'" type="'.e($type).'" value="'.e($value).'"'.($required?' required':'').($type==='number'?' min="0"':'').'></label>'; }
function admin_select(string $name,string $label,array $options,mixed $selected=''): void { echo '<label>'.e($label).'<select name="'.e($name).'">'; foreach($options as $value=>$text) echo '<option value="'.e($value).'"'.((string)$value===(string)$selected?' selected':'').'>'.e($text).'</option>'; echo '</select></label>'; }
function admin_end(string $label='Save changes'): void { echo '<button class="btn small">'.e($label).'</button></form>'; }
?>
<section class="admin-shell"><aside class="admin-nav"><p class="eyebrow">WIKI / CONTROL ROOM</p><?php foreach(Admin::SECTIONS as $key=>[$label,$perm]) if(allowed($perm)): ?><a class="<?=$section===$key?'selected':''?>" href="/admin/<?=e($key)?>"><?=e($label)?></a><?php endif ?></aside><div class="admin-main"><div class="section-heading"><div><p class="eyebrow">A LITTLE CLARITY. A LOT OF POSSIBILITY.</p><h1><?=e(Admin::SECTIONS[$section][0])?></h1></div><a class="underlined" href="/">View store ↗</a></div>
<?php if($section==='dashboard'): $stats=[
'Collected revenue'=>money((int)query("SELECT COALESCE(SUM(total),0) FROM orders WHERE payment_status='paid'")->fetchColumn()),
'Today collected'=>money((int)query("SELECT COALESCE(SUM(total),0) FROM orders WHERE payment_status='paid' AND DATE(created_at)=UTC_DATE()")->fetchColumn()),
'Total orders'=>query('SELECT COUNT(*) FROM orders')->fetchColumn(),
'Open orders'=>query("SELECT COUNT(*) FROM orders WHERE status IN ('pending','confirmed','processing')")->fetchColumn(),
'Delivered orders'=>query("SELECT COUNT(*) FROM orders WHERE status='delivered'")->fetchColumn(),
'Products'=>query("SELECT COUNT(*) FROM products WHERE status<>'archived'")->fetchColumn(),
'Low stock variants'=>query('SELECT COUNT(*) FROM inventory WHERE stock<=minimum_stock')->fetchColumn(),
'Customers'=>query('SELECT COUNT(*) FROM users WHERE role_id=1')->fetchColumn(),
'Returns'=>query('SELECT COUNT(*) FROM returns')->fetchColumn(),
'Refunded amount'=>money((int)query('SELECT COALESCE(SUM(amount),0) FROM refunds')->fetchColumn())]; ?><div class="stats-grid"><?php foreach($stats as $label=>$value): ?><article><small><?=e($label)?></small><strong><?=e($value)?></strong></article><?php endforeach ?></div><div class="two-grid"><div class="panel"><h2>Sales over time</h2><p class="muted">Order value · last 14 active days</p><?php $daily=query("SELECT DATE(created_at) day,SUM(total) total,COUNT(*) count FROM orders WHERE status NOT IN ('cancelled','refunded') GROUP BY DATE(created_at) ORDER BY day DESC LIMIT 14")->fetchAll(); $max=max(array_merge([1],array_column($daily,'total'))); foreach(array_reverse($daily) as $d): ?><div class="chart-row"><span><?=e($d['day'])?></span><meter min="0" max="<?=e($max)?>" value="<?=e($d['total'])?>"><?=e($d['total'])?></meter><small><?=money($d['total'])?> / <?=e($d['count'])?> orders</small></div><?php endforeach ?><?php if(!$daily): ?><p>Sales will appear after your first order.</p><?php endif ?></div><div class="panel"><h2>Top-selling products</h2><?php foreach(query("SELECT i.name,SUM(i.quantity) sold FROM order_items i JOIN orders o ON o.id=i.order_id WHERE o.status NOT IN ('cancelled','refunded','returned') GROUP BY i.product_id,i.name ORDER BY sold DESC LIMIT 5")->fetchAll() as $top): ?><p><?=e($top['name'])?> <strong><?=e($top['sold'])?> sold</strong></p><?php endforeach ?><h3>Sales by category</h3><?php foreach(query("SELECT c.name,SUM(i.quantity*i.unit_price) amount FROM order_items i JOIN orders o ON o.id=i.order_id JOIN products p ON p.id=i.product_id JOIN categories c ON c.id=p.category_id WHERE o.status NOT IN ('cancelled','refunded','returned') GROUP BY c.id,c.name")->fetchAll() as $c): ?><p><?=e($c['name'])?> · <?=money($c['amount'])?></p><?php endforeach ?></div></div><div class="panel"><h2>Inventory alerts</h2><?php foreach(query('SELECT v.sku,i.stock FROM inventory i JOIN product_variants v ON v.id=i.variant_id WHERE i.stock<=i.minimum_stock LIMIT 15')->fetchAll() as $row): ?><p><?=e($row['sku'])?> <span class="badge"><?=e($row['stock'])?> remaining</span></p><?php endforeach ?></div>
<?php else: ?>
<?php if($section==='products'): $edit=isset($_GET['edit'])?query('SELECT * FROM products WHERE id=?',[(int)$_GET['edit']])->fetch():[]; $edit=$edit?:[]; ?><details class="admin-editor" <?=isset($_GET['edit'])?'open':''?>><summary><?=isset($_GET['edit'])?'Edit product':'Create product'?> +</summary><?php admin_start('product',$section); ?><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><?php foreach(['name'=>'Product name','slug'=>'URL slug','sku'=>'SKU'] as $key=>$label) admin_field($key,$label,'text',$edit[$key]??''); admin_select('type','Product type',['clothing'=>'Clothing','scents'=>'Scents'],$edit['type']??'clothing'); admin_select('category_id','Category',array_column(query('SELECT id,name FROM categories ORDER BY name')->fetchAll(),'name','id'),$edit['category_id']??1); foreach(['price'=>'Regular price (minor units)','sale_price'=>'Sale price (optional, minor units)','cost_price'=>'Cost price (minor units)'] as $key=>$label) admin_field($key,$label,'number',$edit[$key]??($key==='cost_price'?0:''),$key!=='sale_price'); admin_select('status','Status',['active'=>'Active','draft'=>'Draft','archived'=>'Archived'],$edit['status']??'draft'); ?><label class="check"><input type="checkbox" name="featured" <?=!empty($edit['featured'])?'checked':''?>> Featured</label><label class="wide">Short description<textarea name="short_description" maxlength="500" required><?=e($edit['short_description']??'')?></textarea></label><label class="wide">Description<textarea name="description" required><?=e($edit['description']??'')?></textarea></label><?php foreach(['fragrance_family','top_notes','middle_notes','base_notes','gender','longevity','concentration'] as $key) admin_field($key,ucwords(str_replace('_',' ',$key)),'text',$edit[$key]??'',false); admin_end(); ?></details><details class="admin-editor"><summary>Upload product photography +</summary><?php admin_start('upload',$section,true); admin_field('product_id','Product ID','number',$edit['id']??''); admin_field('image','Image (JPEG, PNG, WebP; maximum 5 MB)','file'); admin_field('alt','Descriptive alternative text'); admin_field('position','Gallery order (0 = main)','number',0); admin_end('Upload image'); ?></details>
<?php elseif($section==='categories'): ?><details class="admin-editor"><summary>Add category or subcategory +</summary><?php admin_start('category',$section); admin_field('name','Category name'); admin_field('slug','URL slug'); admin_select('parent_id','Parent category',[0=>'No parent']+array_column(query('SELECT id,name FROM categories')->fetchAll(),'name','id')); admin_end(); ?></details>
<?php elseif($section==='variants'): ?><details class="admin-editor"><summary>Add variant +</summary><?php admin_start('variant',$section); admin_field('product_id','Product ID','number'); admin_field('sku','Unique SKU'); foreach(['size','color','volume'] as $key) admin_field($key,ucfirst($key),'text','',false); admin_field('price_adjustment','Price addition (minor units)','number',0); admin_field('stock','Stock','number',0); admin_field('minimum_stock','Low-stock threshold','number',5); admin_end(); ?></details>
<?php elseif($section==='inventory'): ?><details class="admin-editor"><summary>Adjust stock +</summary><?php admin_start('inventory',$section); admin_field('id','Variant ID','number',$_GET['edit']??''); admin_field('stock','New stock count','number'); admin_field('minimum_stock','Low-stock threshold','number',5); admin_field('reason','Adjustment reason'); admin_end(); ?></details>
<?php elseif($section==='orders'): ?><details class="admin-editor" <?=isset($_GET['edit'])?'open':''?>><summary>Manage an order +</summary><?php admin_start('order',$section); admin_field('id','Order ID','number',$_GET['edit']??''); admin_select('status','Next status',array_combine(['confirmed','processing','shipped','out_for_delivery','delivered','cancelled','returned'],['Confirmed','Processing','Shipped','Out for delivery','Delivered','Cancelled','Returned'])); admin_end('Update status'); admin_start('shipment',$section); admin_field('id','Order ID','number',$_GET['edit']??''); admin_field('carrier','Carrier'); admin_field('tracking_number','Tracking number'); admin_end('Save shipment'); admin_start('paid',$section); admin_field('id','Delivered COD order ID','number',$_GET['edit']??''); admin_end('Confirm cash collected'); ?></details><?php if(isset($_GET['edit'])): $o=query('SELECT * FROM orders WHERE id=?',[(int)$_GET['edit']])->fetch(); if($o): ?><article class="panel"><h2><?=e($o['number'])?></h2><p><?=e($o['customer_name'].' · '.$o['email'].' · '.$o['phone'])?></p><p><?=e(implode(', ',json_decode($o['shipping_address'],true)))?></p><p>Notes: <?=e($o['notes'])?></p><?php foreach(query('SELECT * FROM order_items WHERE order_id=?',[$o['id']])->fetchAll() as $line): ?><p><?=e($line['sku'].' · '.$line['name'].' · '.$line['variant'].' × '.$line['quantity'])?></p><?php endforeach ?></article><?php endif; endif ?>
<?php elseif($section==='refunds'): ?><div class="panel"><p>Record a refund only after returning money through the original payment channel. This form records reconciliation; it does not transfer funds.</p><?php admin_start('refund',$section); admin_field('id','Order ID','number'); admin_field('amount','Refund amount (minor units)','number'); admin_field('reference','Unique bank / provider reference'); admin_end('Record completed refund'); ?></div>
<?php elseif($section==='returns'): ?><details class="admin-editor"><summary>Manage return +</summary><?php admin_start('return-status',$section); admin_field('id','Return ID','number'); admin_select('status','Next status',['approved'=>'Approved','rejected'=>'Rejected','received'=>'Received']); admin_end(); ?></details>
<?php elseif($section==='reviews'): ?><details class="admin-editor"><summary>Moderate review +</summary><?php admin_start('review',$section); admin_field('id','Review ID','number'); admin_select('status','Status',['approved'=>'Approve','rejected'=>'Reject']); admin_end(); ?></details><details class="admin-editor"><summary>Delete review</summary><p>Deletion is permanent. Rejection keeps the moderation history.</p><?php admin_start('review-delete',$section); admin_field('id','Review ID','number'); admin_end('Permanently delete review'); ?></details>
<?php elseif($section==='coupons'): ?><details class="admin-editor"><summary>Create coupon +</summary><?php admin_start('coupon',$section); admin_field('code','Code'); admin_select('type','Discount type',['percentage'=>'Percentage','fixed'=>'Fixed amount']); foreach(['value'=>'Discount value (% or minor units)','minimum_amount'=>'Minimum spend (minor units)','maximum_discount'=>'Maximum discount (0 = no cap)','usage_limit'=>'Total usage limit','per_user_limit'=>'Per-account limit'] as $key=>$label) admin_field($key,$label,'number',in_array($key,['usage_limit','per_user_limit'])?1:0); admin_field('starts_at','Starts at (UTC)','datetime-local',gmdate('Y-m-d\TH:i')); admin_field('expires_at','Expires at (UTC)','datetime-local'); ?><label class="check"><input type="checkbox" name="active" checked> Active</label><?php admin_end(); ?></details>
<?php elseif($section==='banners'): ?><details class="admin-editor"><summary>Create banner +</summary><?php admin_start('banner',$section); admin_field('title','Title'); admin_field('body','Message'); admin_field('url','Storefront link','text','/shop'); admin_end(); ?></details>
<?php elseif($section==='settings'): ?><div class="panel"><?php admin_start('setting',$section); admin_select('name','Setting',['announcement'=>'Announcement','contact_email'=>'Contact email','instagram_url'=>'Instagram URL']); admin_field('value','Value'); admin_end(); ?></div>
<?php elseif($section==='users'): ?><details class="admin-editor"><summary>Assign an account role +</summary><p>Customer accounts are created through registration. Assign administrator or fulfillment access here.</p><?php admin_start('role',$section); admin_field('id','User ID','number'); admin_select('role_id','Role',[1=>'Customer',2=>'Administrator',3=>'Fulfillment']); admin_end(); ?></details>
<?php elseif($section==='analytics'): ?><p>Last 30 days. Activity is collected only after opt-in. Order reports include all transactions; this is not a complete marketing attribution system.</p>
<?php elseif($section==='roles'): ?><p>Administrator: full operational access. Fulfillment: orders and reports. Customer: own account only. Permission mappings are installed with the schema.</p>
