<?php $rows=Admin::rows($section); if($rows): ?><div class="table-scroll"><table><thead><tr><?php foreach(array_keys($rows[0]) as $key): ?><th><?=e(ucwords(str_replace('_',' ',$key)))?></th><?php endforeach ?><th>Action</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><?php foreach($row as $key=>$value): ?><td><?=e(in_array($key,['price','sale_price','total','amount','ordered_value','collected_revenue'],true)&&$value!==null?money((int)$value):$value)?></td><?php endforeach ?><td><?php if(in_array($section,['products','orders','inventory'],true)): ?><a class="underlined" href="/admin/<?=e($section)?>?edit=<?=e($row['id'])?>">Manage</a><?php endif ?><?php $toggle=['products'=>'archive','coupons'=>'coupon-toggle','banners'=>'banner-toggle','newsletter'=>'unsubscribe'][$section]??null; if($toggle): ?><form method="post" action="/admin/<?=e($section)?>" data-confirm="Apply this change?"><?=csrf_field()?><input type="hidden" name="action" value="<?=e($toggle)?>"><input type="hidden" name="section" value="<?=e($section)?>"><input type="hidden" name="id" value="<?=e($row['id'])?>"><button class="text-button"><?=e(['archive'=>'Archive','coupon-toggle'=>'Toggle active','banner-toggle'=>'Toggle active','unsubscribe'=>'Unsubscribe'][$toggle])?></button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php else: ?><div class="empty-state"><h2>A clean slate.</h2><p>Records will appear here as your store grows.</p></div><?php endif ?><nav class="pagination"><?php $pg=max(1,(int)($_GET['page']??1)); if($pg>1): ?><a href="?page=<?=$pg-1?>">← Previous</a><?php endif ?><span>Page <?=$pg?></span><?php if(count($rows)===50): ?><a href="?page=<?=$pg+1?>">Next →</a><?php endif ?></nav><?php endif ?></div></section>
